export default function CoreValues() {
  return (
    <section className="w-full py-8 sm:py-12 lg:py-16 font-manrope">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Main Card Container */}
        <div className="relative rounded-2xl border border-[#3e3116] bg-[#0c0904] p-6 sm:p-8 lg:p-12 shadow-[0_0_50px_rgba(255,187,0,0.06)]">
          {/* Header */}
          <div className="flex flex-col items-start">
            <h2 className="text-2xl sm:text-3xl font-semibold text-white tracking-tight">
              Core Values
            </h2>
            <div className="w-14 h-[3px] bg-[#FFBB00] mt-3 rounded-full mb-8 sm:mb-12" />
          </div>

          {/* 6 Value Cards in Row */}
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-6 sm:gap-8 items-start">
            {coreValues.map((value) => (
              <div
                key={value.id}
                className="group flex flex-col items-center text-center"
              >
                {/* Circular Icon Container */}
                <div className="flex h-14 w-14 sm:h-16 sm:w-16 items-center justify-center rounded-full border border-[#3a2d15] bg-transparent transition-all duration-300 group-hover:border-[#FFBB00]/60 group-hover:scale-105 group-hover:shadow-[0_0_20px_rgba(255,187,0,0.15)]">
                  {value.icon}
                </div>

                {/* Title */}
                <h3 className="mt-4 sm:mt-5 font-manrope text-base sm:text-lg font-semibold text-white transition-colors duration-200 group-hover:text-[#FFEAB1]">
                  {value.title}
                </h3>

                {/* Description */}
                <p className="mt-2 font-inter text-xs leading-relaxed text-[#948b7d] max-w-[190px]">
                  {value.description}
                </p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}